:root{
  --bg:#050506; --panel:#0a0b0d; --line:#2a1414; --red:#ff1f3d; --red-dim:#7a0e1e;
  --red-glow:#ff3355; --text:#e8e6e6; --text-dim:#8a8a8f; --mono:'IBM Plex Mono','Courier New',monospace;
  --face:'Rajdhani','Arial Narrow',sans-serif;
}
*{box-sizing:border-box;}
html,body{height:100%;margin:0;}
body{
  background:var(--bg); color:var(--text); font-family:var(--face);
  overflow:hidden; position:relative;
  padding-top:env(safe-area-inset-top,0px); padding-bottom:env(safe-area-inset-bottom,0px);
}
@font-face{font-family:'Rajdhani';src:local('Arial Narrow');}

/* ---- background layers ---- */
#canvas-rain{position:fixed;inset:0;z-index:0;opacity:.34;}
.bot-ghost{
  position:fixed; top:50%; left:50%; width:min(78vw,780px); height:min(78vw,780px);
  transform:translate(-50%,-50%); z-index:0; pointer-events:none;
  background-image:url('data:image/png;base64,');
  background-size:contain; background-repeat:no-repeat; background-position:center;
  filter:grayscale(5%) contrast(1.25) brightness(1.05) saturate(1.2);
  opacity:.5; mix-blend-mode:screen;
  animation:ghostFloat 9s ease-in-out infinite, ghostFlicker 6.3s steps(1) infinite;
}
@keyframes ghostFloat{
  0%,100%{transform:translate(-50%,-50%) scale(1);}
  50%{transform:translate(-50%,-52%) scale(1.015);}
}
@keyframes ghostFlicker{
  0%,92%,100%{opacity:.5;}
  93%{opacity:.28;}
  94%{opacity:.62;}
  95%{opacity:.35;}
}
.scanlines{
  position:fixed; inset:0; z-index:1; pointer-events:none;
  background:repeating-linear-gradient(0deg, rgba(255,20,50,.035) 0px, rgba(255,20,50,.035) 1px, transparent 1px, transparent 3px);
}
.vignette{position:fixed;inset:0;z-index:1;pointer-events:none;
  background:radial-gradient(ellipse at center, transparent 55%, rgba(0,0,0,.6) 100%);}

/* ---- shell ---- */
.shell{position:relative; z-index:2; height:100dvh; display:flex; flex-direction:column;}

.topbar{
  display:flex; align-items:center; justify-content:space-between;
  padding:14px 22px; border-bottom:1px solid var(--line);
  background:linear-gradient(180deg, rgba(15,5,7,.9), rgba(10,3,4,.6));
  backdrop-filter:blur(4px);
}
.brand{display:flex; align-items:center; gap:10px;}
.brand-mark{width:14px;height:14px; background:var(--red); clip-path:polygon(50% 0,100% 50%,50% 100%,0 50%); box-shadow:0 0 12px var(--red-glow); animation:pulseMark 2.4s ease-in-out infinite;}
@keyframes pulseMark{0%,100%{opacity:1;}50%{opacity:.4;}}
.brand-name{font-size:20px; font-weight:700; letter-spacing:2px; color:var(--text);}
.brand-name span{color:var(--red);}
.status-pill{display:flex; align-items:center; gap:8px; font-family:var(--mono); font-size:12px; color:var(--text-dim);}
.dot{width:8px;height:8px;border-radius:50%;background:var(--red);box-shadow:0 0 8px var(--red-glow); animation:blink 1.8s infinite;}
@keyframes blink{0%,100%{opacity:1;}50%{opacity:.35;}}
.clock{font-family:var(--mono); font-size:13px; color:var(--text-dim);}

.main{flex:1; display:grid; grid-template-columns:220px 1fr 240px; gap:14px; padding:14px 18px; min-height:0;}
@media (max-width:900px){ .main{grid-template-columns:1fr;} .side{display:none;} }

.panel{
  background:linear-gradient(180deg, rgba(20,8,10,.55), rgba(8,3,4,.55));
  border:1px solid var(--line); border-radius:6px; padding:14px;
  backdrop-filter:blur(6px);
}
.panel-title{font-family:var(--mono); font-size:11px; letter-spacing:2px; color:var(--red); margin:0 0 12px 0; opacity:.85;}

/* left: system status */
.side.left{display:flex; flex-direction:column; gap:14px; overflow-y:auto;}
.metric{margin-bottom:12px;}
.metric-label{display:flex; justify-content:space-between; font-family:var(--mono); font-size:11px; color:var(--text-dim); margin-bottom:5px;}
.bar{height:5px; background:#1a0a0c; border-radius:3px; overflow:hidden;}
.bar-fill{height:100%; background:linear-gradient(90deg,var(--red-dim),var(--red)); box-shadow:0 0 6px var(--red-glow); transition:width .6s ease;}
.net-row{display:flex; justify-content:space-between; font-family:var(--mono); font-size:12px; padding:6px 0; border-top:1px solid var(--line); color:var(--text-dim);}
.net-row b{color:var(--text);}
.task-count{display:flex; gap:10px;}
.count-box{flex:1; text-align:center; padding:10px 6px; border:1px solid var(--line); border-radius:4px;}
.count-box .n{font-size:22px; font-weight:700; color:var(--red); font-family:var(--mono);}
.count-box .l{font-size:10px; color:var(--text-dim); letter-spacing:1px;}

/* center: chat */
.center{display:flex; flex-direction:column; min-height:0;}
.avatar-row{display:flex; align-items:center; gap:16px; padding:10px 4px 16px;}
.avatar{
  width:56px;height:56px;border-radius:10px; position:relative; flex-shrink:0;
  background:radial-gradient(circle at 35% 30%, #2a0d12, #0a0304 70%);
  border:1px solid var(--red-dim); display:flex; align-items:center; justify-content:center;
  box-shadow:0 0 22px rgba(255,20,50,.25);
}
.avatar .eye{width:7px;height:16px; background:var(--red); border-radius:3px; margin:0 3px; box-shadow:0 0 10px var(--red-glow); animation:eyeThink 2.4s ease-in-out infinite;}
.avatar-eyes{display:flex;}
@keyframes eyeThink{0%,100%{height:16px;} 50%{height:6px;}}
.avatar-info .label{font-family:var(--mono); font-size:10px; color:var(--text-dim); letter-spacing:2px;}
.avatar-info .state{font-size:17px; font-weight:600; color:var(--text);}
.avatar-info .state em{color:var(--red); font-style:normal;}

.chat-window{flex:1; overflow-y:auto; padding:6px 4px; display:flex; flex-direction:column; gap:12px; min-height:0;}
.msg{max-width:78%; padding:10px 14px; border-radius:8px; font-size:14px; line-height:1.5; animation:msgIn .25s ease;}
@keyframes msgIn{from{opacity:0; transform:translateY(6px);} to{opacity:1; transform:translateY(0);}}
.msg.ai{align-self:flex-start; background:rgba(255,20,50,.08); border:1px solid var(--line); color:var(--text);}
.msg.ai .tag{font-family:var(--mono); font-size:10px; color:var(--red); display:block; margin-bottom:4px; letter-spacing:1px;}
.msg.user{align-self:flex-end; background:#1c1c1f; border:1px solid #333; color:var(--text);}
.msg.user .tag{font-family:var(--mono); font-size:10px; color:var(--text-dim); display:block; margin-bottom:4px; letter-spacing:1px; text-align:right;}

.input-row{display:flex; gap:10px; padding-top:12px; border-top:1px solid var(--line); margin-top:10px;}
.input-row input{
  flex:1; background:#0d0507; border:1px solid var(--line); border-radius:6px; color:var(--text);
  padding:13px 14px; font-family:var(--mono); font-size:13px; outline:none;
}
.input-row input:focus{border-color:var(--red-dim); box-shadow:0 0 0 2px rgba(255,20,50,.12);}
.icon-btn{
  width:44px; background:#120608; border:1px solid var(--line); border-radius:6px; color:var(--text-dim);
  cursor:pointer; font-size:16px; display:flex; align-items:center; justify-content:center; transition:.15s;
}
.icon-btn:hover{color:var(--red); border-color:var(--red-dim);}
.icon-btn.send{background:linear-gradient(180deg,var(--red),#7a0e1e); color:#fff; border:none;}
.icon-btn.send:hover{filter:brightness(1.15);}
.icon-btn.mic.on{color:var(--red); box-shadow:0 0 10px var(--red-glow); animation:blink 1s infinite;}

/* right: tasks */
.side.right{display:flex; flex-direction:column; gap:14px; overflow-y:auto;}
.task-item{display:flex; align-items:center; gap:8px; font-size:13px; padding:7px 0; border-bottom:1px solid var(--line);}
.task-item .mark{width:14px; font-family:var(--mono); color:var(--red);}
.task-item.done{color:var(--text-dim); text-decoration:line-through;}
.progress-wrap{margin-top:8px;}
.progress-label{font-family:var(--mono); font-size:11px; color:var(--text-dim); margin-bottom:6px;}

/* mobile terminal line */
.footer-log{
  font-family:var(--mono); font-size:11px; color:var(--red-dim); padding:6px 22px 10px;
  border-top:1px solid var(--line); white-space:nowrap; overflow:hidden; text-overflow:ellipsis;
}
::-webkit-scrollbar{width:6px;} ::-webkit-scrollbar-thumb{background:var(--red-dim); border-radius:3px;}

@media (prefers-reduced-motion: reduce){
  *{animation-duration:.001ms !important; animation-iteration-count:1 !important;}
}